import{c as t,Q as o,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"How To Fix AI Slop (Using Hermes)","description":"","frontmatter":{"url":"https://x.com/EXM7777/status/2060736517564477901","title":"How To Fix AI Slop (Using Hermes)","author":"EXM7777","archived":"2026-06-01T00:00:00.000Z","handle":"@EXM7777","published":"2026-05-30T00:00:00.000Z","stats":"891 likes · 78 retweets · 2451 bookmarks · 285538 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-05-30-@EXM7777-477901.md","filePath":"research/tweets/2026-05-30-@EXM7777-477901.md","lastUpdated":1780990164000}'),r={name:"research/tweets/2026-05-30-@EXM7777-477901.md"};function n(i,e,l,h,u,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="how-to-fix-ai-slop-using-hermes-—-exm7777" tabindex="-1">How To Fix AI Slop (Using Hermes) — @EXM7777 <a class="header-anchor" href="#how-to-fix-ai-slop-using-hermes-—-exm7777" aria-label="Permalink to &quot;How To Fix AI Slop (Using Hermes) — @EXM7777&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/EXM7777/status/2060736517564477901" target="_blank" rel="noreferrer">https://x.com/EXM7777/status/2060736517564477901</a><strong>作者</strong>：EXM7777（@EXM7777） <strong>發布日期</strong>：2026-05-30 <strong>收錄日期</strong>：2026-06-01 <strong>類型</strong>：Twitter Article <strong>統計</strong>：891 likes · 78 retweets · 2451 bookmarks · 285538 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>There&#39;s a reason some people seem to be constantly shipping the best software, writing incredible content, or generating insane images... They adopted the eval loop, while you...</p><p>You&#39;ve tried better prompts, you&#39;ve switched to the more expensive model, you&#39;ve written longer instructions, you&#39;ve turned on memory, you&#39;ve built context files the size of a novel, and the slop still comes back...</p><p>it comes back because you keep fixing the layer that was never broken</p><p>slop is not a prompt problem, it&#39;s a systems problem, the same way a factory shipping defective units doesn&#39;t have a worker problem, it has a quality-control problem, nobody is checking the output before it leaves the building</p><p>so this is the build, by the end of this read you&#39;ll have a working eval loop running inside hermes, the open-source agent, scoring every output against your standard before it ships, watching your live output after it ships, and turning every failure back into a new test so the quality floor rises on its own</p><p>we build it together, one piece at a time, and the payoff is concrete, clean output you can trust without re-reading it at midnight, a quality number you can actually look at, and slop that gets caught on the way out the door instead of by your audience</p><p>here&#39;s what you&#39;re walking away with:</p><ul><li>the real reason better prompts, bigger models, and memory never kill slop for good, and the one layer that actually does</li><li>the two places slop hides in your work, your content output and your product output, and why the fix is identical for both</li><li>what an eval loop is in plain english, the quality layer very few people run daily, and the reason no one ever told you to build one</li><li>a quality benchmark you can stand up this week, for content and for product, exactly what to measure and what &quot;good&quot; looks like as a number you can read off a screen</li><li>the exact build, step by step, for wiring that whole loop into hermes out of the pieces it already gives you, skills, memory, cron, and approval buttons, so the gate runs without you</li></ul><p>if you came here for &quot;the 5 prompts that fix ai slop,&quot; this is not that piece, those exist and they don&#39;t work, this is the version that does</p><h2 id="you-ve-tried-everything-except-the-one-thing" tabindex="-1">you&#39;ve tried everything except the one thing <a class="header-anchor" href="#you-ve-tried-everything-except-the-one-thing" aria-label="Permalink to &quot;you&#39;ve tried everything except the one thing&quot;">​</a></h2><p>[圖 1]</p><p>a short walk through what you&#39;ve already done:</p><p>you rewrote the prompt, three times, four times, you added examples, you added a persona, you added a &quot;do not&quot; list a mile long</p><p>you upgraded to the frontier model, paid 5x per token, and the output got more confident without getting less generic</p><p>you turned on memory, you built a context file, you fed it your brand voice, your past work, your style guide</p><p>and every single one of those moves bought you a few good generations, then the slop crept back in</p><p>every one of those is an input-side fix, you keep sharpening the thing that generates while ignoring the thing that should be catching, a better gun fired into the dark still hits nothing</p><p>slop is an output-side problem, it&#39;s not that the model can&#39;t produce good work, it&#39;s that you have no way to tell the good work from the bad work before it reaches someone who matters</p><p>there&#39;s no eval loop, there&#39;s no quality benchmark, there&#39;s no scoreboard, so you&#39;re tuning blind, you change a prompt and you feel like it got better, but feeling is not measurement and a feeling doesn&#39;t catch the bad run hiding in the next 50 generations</p><p>so you blame yourself, or your prompt, or your agent setup, or your context engineering, when the missing piece is an entire layer of working with ai that you were never shown</p><h2 id="why-better-prompts-can-t-fix-this-and-why-everyone-keeps-trying-anyway" tabindex="-1">why better prompts can&#39;t fix this (and why everyone keeps trying anyway) <a class="header-anchor" href="#why-better-prompts-can-t-fix-this-and-why-everyone-keeps-trying-anyway" aria-label="Permalink to &quot;why better prompts can&#39;t fix this (and why everyone keeps trying anyway)&quot;">​</a></h2><p>a prompt is a hypothesis, the output is the result, and an eval is the only thing that closes the loop between them</p><p>without that loop you are guessing forever, you tweak the hypothesis, you eyeball one result, you declare victory, and you never find out that the same prompt produces garbage 30% of the time because you only ever looked at the one output in front of you</p><p>the model is non-deterministic, the same prompt run twice gives you two different answers, which means even a <em>perfect</em> prompt produces slop on some percentage of runs and you have no idea which runs until a client or a user is staring at one</p><p>so a perfect prompt isn&#39;t a quality guarantee, it&#39;s a slightly better coin flip, and you&#39;re shipping every flip</p><p>the reason everyone keeps reaching for prompts anyway is simple, the prompt is the only lever you can actually see, you can edit it, and editing it feels like control</p><p>measurement is invisible, nobody sells you a course on it, no one posts a viral thread titled &quot;the eval suite that 10x&#39;d my output,&quot; so the entire conversation stays stuck on the one lever that can&#39;t solve the problem on its own</p><p>the people whose ai output is consistently clean are not better at prompting than you, they just have a second lever you don&#39;t, they measure every output against a standard before it ships, and the measuring is what makes their prompting look like magic</p><h2 id="the-two-places-slop-lives" tabindex="-1">the two places slop lives <a class="header-anchor" href="#the-two-places-slop-lives" aria-label="Permalink to &quot;the two places slop lives&quot;">​</a></h2><p>slop hides in exactly two places, and almost everyone is only looking at one of them</p><p><strong>place 1, your content output</strong></p><p>the tweets, the articles, the emails, the landing pages, the posts, anything you generate with ai and publish under your name</p><p>slop here looks like work that is technically fine and completely hollow, and it sounds like every other ai account on the timeline, correct on the outside, empty on the inside</p><p>it dies in public and you can&#39;t articulate why because each individual piece looked okay when you hit send</p><p><strong>place 2, your product output</strong></p><p>the ai feature you shipped, the agent, the chatbot, the support responder, the extraction pipeline, the thing your users actually touch</p><p>slop here looks like a wrong answer delivered with total confidence, a hallucinated number, a broken json payload, a tone that&#39;s off for the brand, an output that was great in the demo and quietly degraded three deploys later</p><p>it doesn&#39;t die in public, it scales in silence, every user gets a slightly worse experience and most of them never tell you, they just leave</p><p>these are the same disease with the same cure: content slop and product slop are both un-measured ai output going straight to an audience with no gate in between. the only difference is stakes and visibility, content slop embarrasses you loudly, product slop bleeds you quietly, and the loop we build in hermes grades both with the same skill</p><h2 id="what-an-eval-loop-actually-is" tabindex="-1">what an eval loop actually is <a class="header-anchor" href="#what-an-eval-loop-actually-is" aria-label="Permalink to &quot;what an eval loop actually is&quot;">​</a></h2><p>an eval loop is a repeatable test that scores your ai output against a standard, automatically, every time, before it ships and after it ships</p><blockquote><p>generate the output score it against a benchmark you defined catch the runs that fall below the line fix what&#39;s failing re-score, and let only the passing output through</p></blockquote><p>[圖 2]</p><p>software engineers have had this forever, it&#39;s called testing, you would never ship code with no tests and just hope it works in production, but that is exactly how the entire industry ships ai output right now, straight from the model to the user on a vibe and a prayer</p><p>the reason almost no one has an eval loop is demographic, the people building with ai today came from content, sales, product, founding, not from engineering, so &quot;write tests for your output&quot; was never in the toolkit</p><p>an eval loop runs in three places, and the build ahead puts it in all three:</p><ul><li>before you ship, run your new prompt or model against a saved set of cases and confirm it didn&#39;t get worse (regression testing)</li><li>at runtime, score the output as it&#39;s generated and let conditional logic catch the failures before they reach the user (guardrail)</li><li>in production, score a sample of real executions continuously so you can see quality degrading the day it starts, not the week a client complains</li></ul><p>you can stand up the first one in a spreadsheet, but running all three continuously without it turning into a second job is the whole reason we&#39;re putting this inside an agent</p><p>the moment quality becomes a number, slop stops being a feeling you keep having and becomes a bug you can fix, you can&#39;t debug a vibe, you can debug a score that dropped from 0.82 to 0.61</p><h2 id="the-benchmark-the-three-parts-you-re-about-to-build" tabindex="-1">the benchmark: the three parts you&#39;re about to build <a class="header-anchor" href="#the-benchmark-the-three-parts-you-re-about-to-build" aria-label="Permalink to &quot;the benchmark: the three parts you&#39;re about to build&quot;">​</a></h2><p>a benchmark has three parts, they&#39;re the same three parts whether you&#39;re grading content or grading a product:</p><blockquote><p>test cases, real inputs paired with what good output looks like (your ground truth) metrics, how you turn an output into a score, ideally 0 to 1 a threshold, the line below which nothing ships</p></blockquote><p><strong>for content: your test cases are your gold standard</strong></p><p>pull 20 to 50 of your best pieces, the bangers, the posts that got bookmarked, the articles you&#39;d put your whole name behind. this is what &quot;good&quot; looks like, you&#39;re not inventing a standard, you&#39;re extracting the one you already hit on your best days</p><p><strong>for content: your metric is a rubric</strong></p><p>a score is only as good as the rubric behind it. for content, grade every piece on four criteria:</p><ol><li>it explains how to do something specific, not a vibe, an action the reader can take tomorrow</li><li>anyone in the audience can follow it, no jargon walls, no inside-baseball</li><li>it&#39;s structured, replicable, step by step, not just inspirational</li><li>it&#39;s novel, the reader had no idea you could do this</li></ol><p>the meta-criterion sitting on top of all four: would someone bookmark this and come back to implement it later? if the answer is no it&#39;s slop no matter how clean the prose reads</p><p>the trick is the rubric: a vague rubric (&quot;is this good and engaging&quot;) produces a vague score, a specific rubric (&quot;does this contain at least one copy-paste-able template or playbook&quot;) produces a score you can trust</p><p><strong>for product: your test cases come from your logs</strong></p><p>pull the actual inputs your feature sees, from your logs, from real user sessions, not the three happy-path examples you tested on launch day</p><p><strong>for product: your metric matches the task</strong></p><p>for each input, define what a correct output looks like, then match the metric to the task: exact match for classification, a validator for structure, semantic similarity plus a judge for open-ended output</p><p><strong>for both: the threshold is the line you hold</strong></p><p>0.7 is a reasonable place to start, anything below 0.7 gets reworked or killed before it ships, no exceptions</p><h2 id="building-the-loop-inside-hermes" tabindex="-1">building the loop inside hermes <a class="header-anchor" href="#building-the-loop-inside-hermes" aria-label="Permalink to &quot;building the loop inside hermes&quot;">​</a></h2><p>hermes does not ship an evals button, what hermes gives you instead is better: the raw pieces of an eval loop as primitives you assemble once and then own</p><p><strong>move 1: stand hermes up where it can reach you</strong></p><p>install it and connect it to telegram. hermes runs across 20+ channels and ships native approval buttons into slack and telegram, so the agent can do work in the background and tap you on the shoulder when a decision is yours</p><p><strong>move 2: load your gold standard into memory</strong></p><p>hermes has persistent memory that grows across sessions with full cross-session recall, so the 20 to 50 best pieces from your benchmark go in there once and stay, the ground truth your scores get measured against</p><p><strong>move 3: turn your rubric into a judge skill</strong></p><p>tell hermes once, in plain english, to create a skill that takes an output plus your rubric and returns a 0 to 1 score per criterion with a one-line reason. that&#39;s llm-as-a-judge: an agent grading your llm, and a model with a sharp rubric is a more consistent critic than you are because it has no ego in the piece</p><p>the reason this lives as a skill and not a one-off prompt: hermes skills are procedural memory. nous found agents with 20+ self-created skills finish similar tasks 40% faster because they stop rediscovering the process</p><p>[圖 4]</p><p><strong>move 4: make the suite a skill, not a spreadsheet</strong></p><p>your test cases plus the metric functions become a skill hermes holds and versions. exact match for classification, regex for extraction, json validators for structure, semantic similarity for generative output. hermes writes the scoring code itself, you describe the task and it builds the metric</p><p><strong>move 5: gate the ship with regression testing and an approval button</strong></p><p>wire it so any change (a new prompt, a swapped model, a tweaked pipeline) triggers the suite. hermes re-runs every case, computes the score delta against baseline, and instead of silently shipping it pings you in slack: &quot;scores went 0.81 to 0.74, two cases regressed, approve?&quot; and it only advances when you tap the button</p><p>[圖 5]</p><p><strong>move 6: watch production on a cron and close the loop</strong></p><p>schedule a job that samples real executions, scores them with the same judge skill, and dms you the moment the line dips. when you flag a bad output with a thumbs-down in slack, hermes writes it back into the suite skill as a new test case. that failed run becomes a permanent check, and the suite hardens every week on its own, the floor rises while you sleep</p><p>[圖 6]</p><h2 id="the-part-nobody-wants-to-hear" tabindex="-1">the part nobody wants to hear <a class="header-anchor" href="#the-part-nobody-wants-to-hear" aria-label="Permalink to &quot;the part nobody wants to hear&quot;">​</a></h2><p>the reason your ai output is inconsistent is not that you&#39;re bad at prompting, and it&#39;s not that the model isn&#39;t smart enough yet</p><p>it&#39;s that you&#39;re running a generation step with no quality step, you built half a system and you&#39;ve been blaming the half that works</p><p>the fix isn&#39;t a better prompt, it&#39;s a missing layer: define what good looks like, turn it into a number, score every output against it, gate everything that falls below the line, and close the loop so the floor rises every week</p><p>do that and slop stops being a thing that randomly happens to you and becomes a thing you catch on the way out the door, every time, the same way a real factory catches a defect before it ever reaches a customer</p><p>the prompt was never the system</p><p>the eval loop is the system, hermes is where it runs, and now you have it</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Slop 是 output 缺乏評量的問題（非 prompt 問題）——建立 eval loop：定義 rubric → 每次輸出評分 → 低於閾值攔截 → 失敗案例沉澱為新測試，在 Hermes 六步驟實作。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Slop = output-side 問題</strong>：prompt/model/memory 都是 input-side 修補，但 model 非確定性，完美 prompt 仍有 30% 機率出爛貨，缺少評量層才是根因</li><li><strong>Eval loop = AI 版 unit testing</strong>：generate → score → catch failure → fix → gate，工程師早有這個，內容/產品創作者都沒有</li><li><strong>Benchmark 三要素</strong>：測試案例（20-50 最佳作品）+ 評分 rubric（具體 4 維度）+ 閾值（0.7）</li><li><strong>Hermes 六步驟</strong>：安裝接通知頻道 → 記憶存 ground truth → rubric 變 judge skill → test suite 版本化 → 每次發布前回歸測試+審批按鈕 → cron 監控生產環境評分</li><li><strong>失敗案例自動硬化 test suite</strong>：thumbs-down → 寫回 suite → quality floor 自動週週上升</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Nous 研究：agent 有 20+ self-created skills 後，相似任務完成速度快 40%</li><li>評分閾值：0.7（低於此分全攔截）</li><li>Hermes 支援 20+ 頻道，Slack/Telegram 原生審批按鈕</li><li>四維度評分 rubric：① 具體可操作步驟 ② 受眾可理解 ③ 結構可複製 ④ 具有新意</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>概念非原創</strong>：eval loop 在 ML 工程中早已存在；作者的貢獻是將 ML evals 普及化給非工程背景的 AI 使用者</li><li><strong>過度 Hermes 綁定</strong>：eval loop 概念可應用於 Claude Code/Codex 任何 agent 框架，文章卻整篇以 Hermes 為前提</li><li><strong>LLM-as-a-judge 可靠性未討論</strong>：用 LLM 評 LLM 輸出，judge 本身也是非確定性的，一致性問題沒有處理方案</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>六步驟具體，rubric 模板可直接套用到 Claude Code workspace</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>「非工程師的 eval loop」切入點有新意，概念本身非原創</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>Nous 40% 數據具體，但大多是邏輯論述，缺乏作者自身量化結果</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>涵蓋 LLM-as-a-judge/regression testing/cron monitoring，技術面完整</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Eval loop 原則適用所有 AI 工作流，概念跨工具、跨場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.3/10</strong></td><td>8×0.3+7×0.2+6×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：「Eval loop 作為 AI 輸出品質控制層」是可直接應用於 Claude Code workspace 的設計原則，rubric 四維度可直接移植為 R9 測試驗證意圖的具體實作。</p>',107)])])}const y=t(r,[["render",n]]);export{c as __pageData,y as default};
